package study.s24;

import org.yaml.snakeyaml.LoaderOptions;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.SafeConstructor;

import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;

/**
 * AX 유스케이스 ROI 계산기 — Python 트랙 roi.py 와 같은 식, 같은 usecases.yaml.
 *   ./mvnw -q compile exec:java -Dexec.args="usecases.yaml --md"
 *
 * 연간 절감 시간 = 사용자 × 하루 절감 분 ÷ 60 × 근무일 × 활용률 × (1 − 검토 비율)
 * 연간 순효과   = 절감 시간 × 시간당 인건비 − 연간 운영비
 * 회수 기간(월) = 초기 구축비 ÷ (연간 순효과 ÷ 12)
 * 3년 ROI      = (3 × 연간 순효과 − 초기 구축비) ÷ 초기 구축비
 * 결과는 입력값에 따른 '추정'입니다. 파일럿 실측값으로 다시 계산하세요.
 */
public final class Roi {

    public record Assumptions(double hourlyCost, double workDays, double adoptionRate, double reviewRatio) {
        Assumptions withAdoption(double rate) {
            return new Assumptions(hourlyCost, workDays, rate, reviewRatio);
        }
    }

    public record UseCase(String name, double users, double minutesSaved, double oneTimeCost, double annualRunCost,
                          int effect, int difficulty, String source) {
        UseCase scaleMinutes(double s) {
            return new UseCase(name, users, minutesSaved * s, oneTimeCost, annualRunCost, effect, difficulty, source);
        }
    }

    public record Row(UseCase uc, double hours, double saving, double net, double payback, double roi3, String quadrant) {}

    public static Row evaluate(UseCase u, Assumptions a) {
        double hours = u.users() * u.minutesSaved() / 60 * a.workDays() * a.adoptionRate() * (1 - a.reviewRatio());
        double saving = hours * a.hourlyCost();
        double net = saving - u.annualRunCost();
        double payback = net > 0 ? u.oneTimeCost() / (net / 12) : Double.POSITIVE_INFINITY;
        double roi3 = (3 * net - u.oneTimeCost()) / u.oneTimeCost();
        String quadrant = u.effect() >= 4 && u.difficulty() <= 3 ? "먼저 할 것"
                : u.effect() >= 4 ? "전략 과제"
                : u.difficulty() <= 3 ? "빠른 개선" : "보류";
        return new Row(u, hours, saving, net, payback, roi3, quadrant);
    }

    /** 회수 기간이 짧은 순, 같으면 3년 ROI 가 큰 순 */
    public static List<Row> rank(List<UseCase> ucs, Assumptions a) {
        List<Row> rows = new ArrayList<>();
        for (UseCase u : ucs) rows.add(evaluate(u, a));
        rows.sort(Comparator.comparingDouble(Row::payback).thenComparing(Comparator.comparingDouble(Row::roi3).reversed()));
        return rows;
    }

    // ── 입력 읽기
    public record Config(Assumptions assumptions, List<UseCase> usecases) {}

    @SuppressWarnings("unchecked")
    public static Config load(Path file) throws IOException {
        Map<String, Object> cfg;
        try (Reader r = Files.newBufferedReader(file, StandardCharsets.UTF_8)) {
            cfg = new Yaml(new SafeConstructor(new LoaderOptions())).load(r);
        }
        Map<String, Object> a = (Map<String, Object>) cfg.get("assumptions");
        Assumptions as = new Assumptions(num(a, "hourly_cost_krw"), num(a, "work_days_per_year"),
                num(a, "adoption_rate"), num(a, "quality_review_ratio"));
        List<UseCase> ucs = new ArrayList<>();
        for (Map<String, Object> u : (List<Map<String, Object>>) cfg.get("usecases")) {
            ucs.add(new UseCase(String.valueOf(u.get("name")), num(u, "users"), num(u, "minutes_saved_per_user_per_day"),
                    num(u, "one_time_cost_krw"), num(u, "annual_run_cost_krw"),
                    (int) num(u, "effect"), (int) num(u, "difficulty"),
                    String.valueOf(u.getOrDefault("source", "추정(예시)"))));   // 숫자의 근거: 실측·인터뷰·견적·가정
        }
        return new Config(as, ucs);
    }

    static double num(Map<String, Object> m, String k) {
        Object v = m.get(k);
        if (!(v instanceof Number n)) throw new IllegalArgumentException(k + " 값이 숫자가 아닙니다: " + v);
        return n.doubleValue();
    }

    // ── 출력 형식
    public static String won(double x) {
        return String.format("%,.1f백만", x / 1e6);
    }

    public static String months(double payback) {
        return Double.isInfinite(payback) ? "회수 불가" : String.format("%.1f개월", payback);
    }

    public static String pct(double x) {
        return String.format("%.0f%%", x * 100);
    }

    public static String markdownTable(List<Row> rows) {
        StringBuilder sb = new StringBuilder("| 순위 | 유스케이스 | 사분면 | 연간 절감 시간 | 연간 순효과(원) | 회수 기간 | 3년 ROI | 근거 |\n");
        sb.append("|---:|---|---|---:|---:|---:|---:|---|\n");
        for (int i = 0; i < rows.size(); i++) {
            Row r = rows.get(i);
            sb.append(String.format("| %d | %s | %s | %,.0fh | %s | %s | %s | %s |%n", i + 1, r.uc().name(), r.quadrant(),
                    r.hours(), won(r.net()), months(r.payback()), pct(r.roi3()), r.uc().source()));
        }
        return sb.toString();
    }

    public static String assumptionsLine(Assumptions a) {
        return String.format("가정: 시간당 %,.0f원 · 근무일 %.0f일 · 활용률 %s · 검토 비율 %s (예시 값)",
                a.hourlyCost(), a.workDays(), pct(a.adoptionRate()), pct(a.reviewRatio()));
    }

    public static void main(String[] args) throws IOException {
        List<String> files = new ArrayList<>();
        boolean md = false;
        for (String x : args) {
            if (x.equals("--md")) md = true;
            else files.add(x);
        }
        Config cfg = load(Path.of(files.isEmpty() ? "usecases.yaml" : files.get(0)));
        List<Row> rows = rank(cfg.usecases(), cfg.assumptions());
        if (md) {
            System.out.print(markdownTable(rows));
        } else {
            for (int i = 0; i < rows.size(); i++) {
                Row r = rows.get(i);
                System.out.printf("%d. %s [%s]%n", i + 1, r.uc().name(), r.quadrant());
                System.out.printf("   절감 %,.0f시간/년 · 순효과 %s원/년 · 회수 %s · 3년 ROI %s%n",
                        r.hours(), won(r.net()), months(r.payback()), pct(r.roi3()));
            }
        }
        System.out.println("\n" + assumptionsLine(cfg.assumptions()));
    }
}

package study.s24;

import java.io.IOException;
import java.nio.file.Path;
import java.util.List;

/**
 * 민감도 분석 — 활용률과 절감 시간이 예상보다 낮으면 회수 기간이 어떻게 바뀌나 (Python 트랙 sensitivity.py 와 같은 표).
 *   ./mvnw -q compile exec:java -Dexec.mainClass=study.s24.Sensitivity -Dexec.args="usecases.yaml 장애_보고서_초안_자동_작성"
 * 이름의 공백은 exec.args 에서 나뉘므로 밑줄(_)로 적어도 됩니다.
 */
public final class Sensitivity {

    public static final double[] RATES = {0.3, 0.5, 0.7, 0.9};
    public static final double[] SCALES = {0.5, 0.75, 1.0};

    /** [활용률][절감 분 배율] 별 회수 기간(개월) */
    public static double[][] grid(Roi.UseCase uc, Roi.Assumptions a) {
        double[][] g = new double[RATES.length][SCALES.length];
        for (int i = 0; i < RATES.length; i++) {
            for (int j = 0; j < SCALES.length; j++) {
                g[i][j] = Roi.evaluate(uc.scaleMinutes(SCALES[j]), a.withAdoption(RATES[i])).payback();
            }
        }
        return g;
    }

    public static String markdown(Roi.UseCase uc, Roi.Assumptions a) {
        double[][] g = grid(uc, a);
        StringBuilder sb = new StringBuilder("| 활용률 \\ 절감 분 | ×0.5 | ×0.75 | ×1.0 |\n|---:|---:|---:|---:|\n");
        for (int i = 0; i < RATES.length; i++) {
            sb.append("| ").append(Roi.pct(RATES[i]));
            for (double pb : g[i]) sb.append(" | ").append(Double.isInfinite(pb) ? "불가" : String.format("%.1f", pb));
            sb.append(" |\n");
        }
        return sb.toString();
    }

    public static Roi.UseCase find(List<Roi.UseCase> ucs, String name) {
        String key = name.replace('_', ' ');
        return ucs.stream().filter(u -> u.name().equals(key)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("유스케이스 없음: " + key));
    }

    public static void main(String[] args) throws IOException {
        Roi.Config cfg = Roi.load(Path.of(args.length > 0 ? args[0] : "usecases.yaml"));
        Roi.UseCase uc = args.length > 1 ? find(cfg.usecases(), String.join(" ", List.of(args).subList(1, args.length)))
                : cfg.usecases().get(0);
        double[][] g = grid(uc, cfg.assumptions());
        System.out.println("[" + uc.name() + "] 회수 기간(개월) — 행: 활용률, 열: 하루 절감 분 배율");
        System.out.println("활용률  ×0.5   ×0.75  ×1.0");
        for (int i = 0; i < RATES.length; i++) {
            StringBuilder line = new StringBuilder(String.format("%4.0f%%   ", RATES[i] * 100));
            for (double pb : g[i]) line.append(Double.isInfinite(pb) ? "  불가  " : String.format("%5.1f  ", pb));
            System.out.println(line);
        }
    }
}

package study.s24;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * 사업 계획 숫자 보고서(Markdown) — 제안서 템플릿 1장(한 줄 요약) · 4장(숫자) · 5장(위험 등급)에 붙일 내용을 한 파일로 만듭니다.
 *   ./mvnw -q compile exec:java -Dexec.mainClass=study.s24.BusinessCaseReport \
 *     -Dexec.args="usecases.yaml ../../s23/java/review.md"  > business_case.md
 * 두 번째 인자(세션 23 의 review.md)가 있으면 위험 점수·등급과 규제 확인 일자를 읽어 넣습니다.
 */
public final class BusinessCaseReport {

    static final Pattern RISK = Pattern.compile("위험 점수: \\*\\*(\\d+)점 → (\\S+)\\*\\*");
    static final Pattern REG_DATE = Pattern.compile("근거 규정은 (\\d{4}-\\d{2}-\\d{2}) 기준");

    public static String build(Roi.Config cfg, String review, LocalDate today) {
        List<Roi.Row> rows = Roi.rank(cfg.usecases(), cfg.assumptions());
        Roi.Row top = rows.get(0);
        double[][] g = Sensitivity.grid(top.uc(), cfg.assumptions());
        double worst = g[1][0];   // 활용률 50% · 절감 분 ×0.5
        StringBuilder sb = new StringBuilder();
        sb.append("# AX 사업 계획 숫자 — ").append(top.uc().name()).append("\n\n");
        sb.append("> 작성일: ").append(today).append(" · 모든 값은 입력에 따른 추정입니다. 파일럿 실측 후 다시 계산합니다.\n\n");

        sb.append("## 1. 한 줄 요약 (제안서 1장)\n");
        sb.append(String.format("연간 약 %,.0f시간 절감, 회수 기간 약 %s(추정, 파일럿에서 실측 예정).%n",
                top.hours(), Roi.months(top.payback())));
        sb.append(String.format("활용률 50%%·절감 시간 절반에서도 회수 기간 %s 입니다.%n%n", Roi.months(worst)));

        sb.append("## 2. 유스케이스 순위 (제안서 4장)\n");
        sb.append(Roi.markdownTable(rows)).append('\n');
        sb.append("- ").append(Roi.assumptionsLine(cfg.assumptions())).append('\n');
        sb.append("- 근거 열이 '추정(예시)' 인 숫자는 실측·인터뷰·견적으로 바꾼 뒤 usecases.yaml 의 source 에 적습니다.\n\n");

        sb.append("## 3. 2×2 배치 (효과 × 난이도)\n");
        for (String q : List.of("먼저 할 것", "전략 과제", "빠른 개선", "보류")) {
            List<String> names = rows.stream().filter(r -> r.quadrant().equals(q)).map(r -> r.uc().name()).toList();
            sb.append("- ").append(q).append(": ").append(names.isEmpty() ? "없음" : String.join(", ", names)).append('\n');
        }
        if (!top.quadrant().equals("먼저 할 것")) {
            sb.append("- 주의: 회수 기간 1순위가 '먼저 할 것' 칸이 아닙니다. 발표에서 이유를 설명합니다.\n");
        }

        sb.append("\n## 4. 민감도 — ").append(top.uc().name()).append(" 회수 기간(개월)\n");
        sb.append(Sensitivity.markdown(top.uc(), cfg.assumptions())).append('\n');

        sb.append("## 5. 위험 등급 (제안서 5장, 세션 23)\n");
        Matcher risk = review == null ? null : RISK.matcher(review);
        Matcher reg = review == null ? null : REG_DATE.matcher(review);
        if (risk != null && risk.find()) {
            sb.append("- 위험 점수 ").append(risk.group(1)).append("점 → ").append(risk.group(2)).append('\n');
            sb.append("- 규제 확인 일자: ").append(reg.find() ? reg.group(1) : "확인 필요").append(" (심의 전 최신 규정 재확인)\n");
        } else {
            sb.append("- 세션 23 의 risk_assess 결과(review.md)를 두 번째 인자로 주면 여기에 들어갑니다.\n");
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        Roi.Config cfg = Roi.load(Path.of(args.length > 0 ? args[0] : "usecases.yaml"));
        String review = args.length > 1 ? Files.readString(Path.of(args[1]), StandardCharsets.UTF_8) : null;
        System.out.print(build(cfg, review, LocalDate.now()));
    }
}

package study.s24;

import org.junit.jupiter.api.Test;

import java.time.LocalDate;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** 계산식 회귀 테스트 — Python 트랙 roi.py 와 같은 값이 나오는지 고정합니다. ./mvnw test */
class RoiTest {

    static final Roi.Assumptions A = new Roi.Assumptions(60000, 240, 0.7, 0.2);   // usecases.yaml 예시 가정
    static final List<Roi.UseCase> UCS = List.of(
            new Roi.UseCase("장애 보고서 초안 자동 작성", 25, 20, 30_000_000, 12_000_000, 4, 2, "추정(예시)"),
            new Roi.UseCase("ETL 설계서·테이블 정의서 Q&A", 40, 15, 45_000_000, 15_000_000, 4, 3, "추정(예시)"),
            new Roi.UseCase("SQL 코드 리뷰 보조", 15, 25, 25_000_000, 8_000_000, 3, 2, "추정(예시)"),
            new Roi.UseCase("고객 문의 답변 초안", 60, 30, 150_000_000, 40_000_000, 5, 5, "추정(예시)"));

    @Test
    void 장애_보고서_초안의_절감_시간과_회수_기간() {
        Roi.Row r = Roi.evaluate(UCS.get(0), A);
        assertEquals(1120.0, r.hours(), 1e-6);                 // 25 × 20 ÷ 60 × 240 × 0.7 × 0.8
        assertEquals(55_200_000.0, r.net(), 1e-3);             // 1,120h × 60,000원 − 12,000,000원
        assertEquals(30_000_000 / (55_200_000.0 / 12), r.payback(), 1e-9);   // 약 6.5개월
        assertEquals(4.52, r.roi3(), 1e-9);                   // 452%
        assertEquals("먼저 할 것", r.quadrant());
    }

    @Test
    void 순위는_회수_기간이_짧은_순() {
        List<String> order = Roi.rank(UCS, A).stream().map(r -> r.uc().name()).toList();
        assertEquals(List.of("장애 보고서 초안 자동 작성", "SQL 코드 리뷰 보조", "ETL 설계서·테이블 정의서 Q&A", "고객 문의 답변 초안"), order);
    }

    @Test
    void 순효과가_0_이하면_회수_불가() {
        Roi.UseCase loss = new Roi.UseCase("적자", 1, 1, 10_000_000, 50_000_000, 2, 4, "가정");
        assertTrue(Double.isInfinite(Roi.evaluate(loss, A).payback()));
        assertEquals("회수 불가", Roi.months(Roi.evaluate(loss, A).payback()));
    }

    @Test
    void 보고서에_한_줄_요약과_민감도와_위험_등급이_들어간다() {
        String review = "- 위험 점수: **1점 → 낮음**\n- 근거 규정은 2026-10-29 기준으로 확인했습니다.";
        String md = BusinessCaseReport.build(new Roi.Config(A, UCS), review, LocalDate.of(2026, 11, 12));
        assertTrue(md.contains("연간 약 1,120시간 절감"), md);
        assertTrue(md.contains("| 50% |"), md);
        assertTrue(md.contains("위험 점수 1점 → 낮음"), md);
        assertTrue(md.contains("규제 확인 일자: 2026-10-29"), md);
    }
}
